(7209341, 1110140, 64086, '<td valign="top">Fabulous puzzle...love the ''pull'' and the reflected ''push''</td>', 'Fabulous puzzle...love the ''pull'' and the reflected ''push''', '2014-04-28 09:11:47.000000', NULL, 1),
(7209507, 1109753, 173844, '<td valign="top">Well done portrayal of this type of iconic moment.  The interior foreground is cozy and cheerful and the exterior beautifully muted.  The bus is caught at just the precise time of expectancy.  The lighting brings out the lushness of the curtains.  Pitch perfect story telling.</td>', 'Well done portrayal of this type of iconic moment.  The interior foreground is cozy and cheerful and the exterior beautifully muted.  The bus is caught at just the precise time of expectancy.  The lighting brings out the lushness of the curtains.  Pitch perfect story telling.', '2014-04-28 16:15:53.000000', NULL, 1),
(7209512, 1110143, 173844, '<td valign="top">I love how the open window invites us to gaze out at this compelling atmospheric scene.  Such a friendly gesture.  Thank you.  One of my favorites.</td>', 'I love how the open window invites us to gaze out at this compelling atmospheric scene.  Such a friendly gesture.  Thank you.  One of my favorites.', '2014-04-28 16:20:03.000000', NULL, 1),
(7209631, 1110002, 6306, '<td valign="top">The lack of interest in the center of the frame kills this. Compelling windows though.</td>', 'The lack of interest in the center of the frame kills this. Compelling windows though.', '2014-04-28 22:51:25.000000', NULL, 1),
(7209632, 1109812, 6306, '<td valign="top">Convert to black and white.</td>', 'Convert to black and white.', '2014-04-28 22:51:52.000000', NULL, 1),
(7209634, 1109688, 6306, '<td valign="top">There are two subjects here. I''m drawn to the brightest element- the bulldog. Try a crop or a different shooting angle. Nice glass.</td>', 'There are two subjects here. I''m drawn to the brightest element- the bulldog. Try a crop or a different shooting angle. Nice glass.', '2014-04-28 22:54:50.000000', NULL, 1),
(7209636, 1109976, 6306, '<td valign="top">Not enough negative space. Remove the HDR, and crop it to a horizontal pano showing only the bottom windows.</td>', 'Not enough negative space. Remove the HDR, and crop it to a horizontal pano showing only the bottom windows.', '2014-04-28 22:57:48.000000', NULL, 1),
(7209639, 1110177, 6306, '<td valign="top">Tone down the highlight on the forehead. The lips make the shot, and my eyes don''t want to dwell on the forehead. Nice colors.</td>', 'Tone down the highlight on the forehead. The lips make the shot, and my eyes don''t want to dwell on the forehead. Nice colors.', '2014-04-28 23:04:16.000000', NULL, 1),
(7209641, 1109765, 6306, '<td valign="top">The bow needs separation from the cat. Nice lighting but it doesn''t look like natural window light.</td>', 'The bow needs separation from the cat. Nice lighting but it doesn''t look like natural window light.', '2014-04-28 23:07:39.000000', NULL, 1),
(7209643, 1109503, 6306, '<td valign="top">Compelling, but there is an overall lack of deep blacks. The person doesn''t add much to the frame- the tiny door shows the scale of the architecture, so there is no need for the person. In fact, without the person in the frame, the architecture looks even bigger.</td>', 'Compelling, but there is an overall lack of deep blacks. The person doesn''t add much to the frame- the tiny door shows the scale of the architecture, so there is no need for the person. In fact, without the person in the frame, the architecture looks even bigger.', '2014-04-28 23:10:43.000000', NULL, 1),
(7209646, 1109649, 6306, '<td valign="top">What''s better- a photo of a beautifully lit clothesline, or a badly lit photo of the Taj Mahal?  I''ll take the clothesline.</td>', 'What''s better- a photo of a beautifully lit clothesline, or a badly lit photo of the Taj Mahal?  I''ll take the clothesline.', '2014-04-28 23:12:24.000000', NULL, 1),
(7209675, 1109688, 114285, '<td valign="top">Top stuff! 9</td>', 'Top stuff! 9', '2014-04-29 03:22:34.000000', NULL, 1),
(7209676, 1109941, 114285, '<td valign="top">Adorable, and I dig the PP.</td>', 'Adorable, and I dig the PP.', '2014-04-29 03:23:11.000000', NULL, 1),
(7209677, 1110141, 114285, '<td valign="top">Wonderful all around.</td>', 'Wonderful all around.', '2014-04-29 03:23:34.000000', NULL, 1),
