(7209888, 1109683, 173844, '<td valign="top">Lovely, variegated mural-like expanse of windows.  Keeps the eye hopping.  I''m enjoying this.</td>', 'Lovely, variegated mural-like expanse of windows.  Keeps the eye hopping.  I''m enjoying this.', '2014-04-29 16:41:56.000000', NULL, 1),
